            @RequestParam(defaultValue = "0") int pagina, @RequestParam(defaultValue = "50") int tamanho) {
        return ResponseEntity.ok().cacheControl(CacheControl.noStore())
                .body(service.daUnidade(unidadeId, status, pagina, tamanho));
